import type { Activity } from '../types/health.js';

/**
 * Story 323. Telling a Google Calendar class that has been *adopted* apart from one that is still
 * only a live projection of the event.
 *
 * A matched calendar event is synthesized on every read of `GET /activities` (see the server's
 * `health-calendar.service.ts`) and has no row anywhere: no `activities` row, so no
 * `cardio_details` and no `workout_sessions`, which are keyed by `activities.id`. Adoption creates
 * that row — same `source: 'calendar'`, so provenance survives — and from then on it is the
 * owner's to edit like any manual entry.
 *
 * Both shapes therefore carry `source: 'calendar'` and the source alone cannot separate them. The
 * discriminator is the id: a synthesized row's is `cal_<eventId>`, an adopted row's is a uuidv7
 * like every other persisted row. That was already the de facto marker before this story — the
 * edit screen skipped its subtype fetches on it and the day detail refused to make the card
 * clickable — so this file names it once instead of leaving `startsWith('cal_')` scattered across
 * the call sites that must not get it wrong.
 */
const SYNTHESIZED_PREFIX = 'cal_';

/** The stable link back to the Google Calendar event: an adopted row's `external_id`. */
export function calendarExternalId(eventId: string): string {
    return `${SYNTHESIZED_PREFIX}${eventId}`;
}

/**
 * Is this a live projection of a calendar event rather than a stored row?
 *
 * Anything that writes, or that hands an id to something which writes, has to ask. Getting it
 * wrong is not cosmetic: the Health Connect push would claim `clientRecordId` for a session that
 * does not exist (and publish classes not yet attended), and the sync's collision index would
 * `PATCH /activities/cal_<eventId>` at a missing row — a 404 that aborts the whole sync, exactly
 * as story 300's 403 did.
 */
export function isSynthesizedCalendarEvent(activity: Pick<Activity, 'id' | 'source'>): boolean {
    return activity.source === 'calendar' && activity.id.startsWith(SYNTHESIZED_PREFIX);
}

/**
 * Is this row the owner's own record, as opposed to a mirror of something another app wrote?
 *
 * `manual` and adopted `calendar` rows are the owner's: nothing writes them back, so editing one
 * cannot be overwritten or contradicted by a sync. `strava` (the retired API's history) and
 * `health_connect_*` are mirrors whose records belong to their writer — story 253's reason for
 * pinning them read-only, which is about being ingested and not about Strava in particular.
 *
 * A *synthesized* calendar event is not user-owned in the sense that matters here, because there
 * is nothing to own yet; callers that can be handed one must combine this with
 * {@link isSynthesizedCalendarEvent}.
 */
export function isUserOwnedActivity(activity: Pick<Activity, 'source'>): boolean {
    return activity.source === 'manual' || activity.source === 'calendar';
}
